/* cppi::214cb8ff609cfb7d16b672be3c40c8a8c3a1b72785a34dfa2bdf8c14eb9679e3 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-15' and end_date = '2025-04-15')
and start_date = '2025-04-15' and end_date = '2025-04-15'

/* cppi::bb55886936022b3c3599c5d2018d7fb42665936805b87cf0602e2a9c0c9f8474 */
select business_date as date_, security_id, 'MS757951' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-19' and business_date <= date '2025-06-19' and weight_ndo>0 and id_cppib_index = 'MS757951_GR_USD_0_0' and security_id is not null

